// constructors

    public OfficeTest(OfficeService service)
    {
        this.service = service;
        LOGGER.setUseParentHandlers(false);	// only want to output to the provided LogHandler
    }

// test methods
    @Test
    /**
     * Full Create-Read-Update-Delete of a Office, through a OfficeTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on OfficeTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on OfficeTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new Office.
     *
     * @return    Office
     */
    public Office testCreate() throws Throwable {
    Office entity = null;

    LOGGER.info( "OfficeTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Office");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Office" );

    try {
        entity = service.createOffice( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getOfficeId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Office with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Office.
     *
     * @return    Office
     */
    public Office testRead() throws Throwable {
    LOGGER.info( "OfficeTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Office" );

    Office entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Office with primary key" );
    msg.append( theId );

    try {
        entity = service.getOffice( new OfficeFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getOfficeId();

        LOGGER.info( "-- Successfully found Office " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Office.
     *
     * @return    Office
     */
    public Office testUpdate() throws Throwable {
    LOGGER.info( "OfficeTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Office." );

    StringBuilder msg = new StringBuilder( "Failed to update a Office : " );
    Office entity = null;

    try {
        UpdateOfficeCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setOfficeId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Office." );

        entity = service.updateOffice( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Office - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Office.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "OfficeTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Office." );

    try {
        DeleteOfficeCommand deleteCommand = new DeleteOfficeCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Office with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Office with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Offices.
     *
     * @return    Collection
     */
    public List<Office> testGetAll() throws Throwable {
    LOGGER.info( "OfficeTest:testGetAll() - Retrieving Collection of Offices:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Office : " );
    List<Office> collection  = null;

    try {
        // call the static get method on the OfficeService
        collection = service.getAllOffice();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Office currEntity  = null;
            Iterator<Office> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getOfficeId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public OfficeTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


